// Sem sobrecargas: o retorno só pode ser uma união, e a precisão perde-se
function primeiro(valor: string | number[]): string | number {
  return valor[0];
}

const letra = primeiro("olá");     // string | number
const numero = primeiro([10, 20]); // string | number

// @ts-expect-error o tipo declarado é string | number, logo toUpperCase não existe em number
letra.toUpperCase();

// quem chama fica obrigado a estreitar um resultado que já se sabia
if (typeof letra === "string") {
  console.log(letra.toUpperCase()); // "O"
}
console.log(numero); // 10

// Duas assinaturas de sobrecarga: é só isto que quem chama vê
function primeiro(valor: string): string;
function primeiro(valor: number[]): number;
// Assinatura de implementação mais corpo: trata os dois casos
function primeiro(valor: string | number[]): string | number {
  return valor[0];
}

const letra = primeiro("olá");     // string
const numero = primeiro([10, 20]); // number

console.log(letra.toUpperCase()); // "O"
console.log(numero.toFixed(2));   // "10.00"

function idParaTexto(id: string): string;
function idParaTexto(id: number): string;
function idParaTexto(id: string | number): string {
  return typeof id === "string" ? id : id.toString(10);
}

console.log(idParaTexto("a1")); // "a1"
console.log(idParaTexto(7));    // "7"

declare const talvez: string | number;

// @ts-expect-error o argumento encaixa na implementação, mas em nenhuma das duas sobrecargas
idParaTexto(talvez);

// A implementação usa união e parâmetro opcional para servir as duas sobrecargas
function criar(titulo: string): { titulo: string };
function criar(titulo: string, ativo: boolean): { titulo: string; ativo: boolean };
function criar(titulo: string, ativo?: boolean): { titulo: string; ativo?: boolean } {
  return ativo === undefined ? { titulo } : { titulo, ativo };
}

console.log(criar("Aula"));       // { titulo: "Aula" }
console.log(criar("Aula", true)); // { titulo: "Aula", ativo: true }

function medir(valor: string): number;
// @ts-expect-error esta sobrecarga promete aceitar Date, mas a implementação só aceita string
function medir(valor: Date): number;
function medir(valor: string): number {
  return valor.length;
}

console.log(medir("abc")); // 3

// Ordem errada: a sobrecarga geral vem primeiro e apanha todas as chamadas
function lerErrado(chave: string): string | null;
function lerErrado(chave: "porta"): string;
function lerErrado(chave: string): string | null {
  return chave === "porta" ? "8080" : null;
}

// Ordem certa: a sobrecarga específica vem primeiro
function lerCerto(chave: "porta"): string;
function lerCerto(chave: string): string | null;
function lerCerto(chave: string): string | null {
  return chave === "porta" ? "8080" : null;
}

const a = lerErrado("porta"); // string | null
const b = lerCerto("porta");  // string

console.log(a);        // "8080"
console.log(b.length); // 4

// Numa interface basta repetir o método: não há corpo, logo não há implementação
interface Repositorio {
  buscar(id: number): string;
  buscar(ids: number[]): string[];
}

// A implementação vive numa função com sobrecargas, depois ligada ao objeto
function buscar(id: number): string;
function buscar(ids: number[]): string[];
function buscar(alvo: number | number[]): string | string[] {
  return Array.isArray(alvo) ? alvo.map((n) => `item-${n}`) : `item-${alvo}`;
}

const repo: Repositorio = { buscar };

const um = repo.buscar(1);         // string
const lista = repo.buscar([1, 2]); // string[]

console.log(um.toUpperCase()); // "ITEM-1"
console.log(lista.length);     // 2

// Com sobrecargas: cada tipo novo obriga a mais duas linhas
function primeiroOv(itens: string[]): string | undefined;
function primeiroOv(itens: number[]): number | undefined;
function primeiroOv(itens: string[] | number[]): string | number | undefined {
  return itens[0];
}

// Com um genérico (Módulo 05): uma assinatura serve todos os tipos
function primeiroGen<T>(itens: T[]): T | undefined {
  return itens[0];
}

console.log(primeiroOv(["a", "b"])); // "a"
console.log(primeiroGen([1, 2]));    // 1
console.log(primeiroGen([true]));    // true

