function duplicar(valor: string): string;
function duplicar(valor: number): number;
function duplicar(valor: string | number): string | number {
  return typeof valor === "string" ? valor + valor : valor * 2;
}

const texto = duplicar("ab"); // string
const conta = duplicar(21);   // number

console.log(texto.toUpperCase()); // "ABAB"
console.log(conta.toFixed(1));    // "42.0"

type Nivel = "info" | "erro";

function registar(nivel: "erro", mensagem: string): Error;
function registar(nivel: Nivel, mensagem: string): Error | string;
function registar(nivel: Nivel, mensagem: string): Error | string {
  return nivel === "erro" ? new Error(mensagem) : `[info] ${mensagem}`;
}

const falha = registar("erro", "disco cheio"); // Error
console.log(falha.message); // "disco cheio"

const nivelDinamico: Nivel = Math.random() > 0.5 ? "info" : "erro";
const qualquer = registar(nivelDinamico, "ola"); // Error | string
console.log(typeof qualquer); // "object" ou "string"

interface Conversor {
  converter(valor: string): number;
  converter(valores: string[]): number[];
}

function converter(valor: string): number;
function converter(valores: string[]): number[];
function converter(entrada: string | string[]): number | number[] {
  return Array.isArray(entrada)
    ? entrada.map((v) => Number(v))
    : Number(entrada);
}

const conversor: Conversor = { converter };

const unico = conversor.converter("3.5");       // number
const varios = conversor.converter(["1", "2"]); // number[]

console.log(unico.toFixed(1)); // "3.5"
console.log(varios.length);    // 2

declare const misto: string | string[];
// @ts-expect-error encaixa na implementação, mas em nenhuma das sobrecargas declaradas
conversor.converter(misto);

interface Config {
  porta: number;
  host: string;
  debug: boolean;
}

const valores: Config = { porta: 8080, host: "localhost", debug: true };

function ler(chave: "porta"): number;
function ler(chave: "host"): string;
function ler(chave: "debug"): boolean;
function ler(chave: keyof Config): number | string | boolean {
  return valores[chave];
}

const porta = ler("porta"); // number
const host = ler("host");   // string
const debug = ler("debug"); // boolean

console.log(porta.toFixed(0));   // "8080"
console.log(host.toUpperCase()); // "LOCALHOST"
console.log(debug === true);     // true

declare const chaveDinamica: keyof Config;
// @ts-expect-error keyof Config encaixa na implementação, mas em nenhuma das três sobrecargas
ler(chaveDinamica);
